CREATE TABLE earning_corrections (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, workday_earning_id BIGINT NOT NULL REFERENCES workday_earnings(id), workday_time_correction_id BIGINT NOT NULL UNIQUE REFERENCES workday_time_corrections(id), sequence INTEGER NOT NULL, cause VARCHAR(32) NOT NULL, previous_economic_seconds BIGINT NOT NULL, new_economic_seconds BIGINT NOT NULL, previous_amount NUMERIC(24,12), new_amount NUMERIC(24,12), corrected_at TIMESTAMPTZ NOT NULL, CONSTRAINT uk_earning_correction_sequence UNIQUE(workday_earning_id,sequence));
